mapper.select:
select * from book_subject where 1=1

    and book_id = #{bookId}


    and (full_name like concat('%',#{name},'%') or code like concat('%',#{name},'%'))


    and type_id = #{typeId}


    and is_model = #{isModel}

order by code asc

mapper.update:
UPDATE book_subject bs
LEFT JOIN book_subject_period bsp ON bs.subject_id = bsp.subject_id and bsp.year_period = #{yearPeriod}
SET bs.balance = IFNULL(bsp.period_end_balance,bs.balance) where bs.book_id = #{bookId}

UPDATE book_subject bs
LEFT JOIN book_subject_period_temporary bsp ON bs.subject_id = bsp.subject_id and bsp.year_period = #{yearPeriod}
SET bs.balance = IFNULL(bsp.period_balance,bs.balance) where bs.book_id = #{bookId} and bsp.del_flag = '0'
